&lt;/div&gt;
Ces objets sont des vestes, des manteaux, des chemises, des gilets et tous les objets port&#233;s sur le torse ou la poitrine.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; sur le torse &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 500 g et 2,5 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur le torse&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandages-De-Gu&#233;rison-Rapide.html&quot; title=&quot;Bandages de gu&#233;rison rapide&quot;&gt;Bandages de gu&#233;rison rapide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Soignes les plaies et les &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissements de caract&#233;ristiques&lt;/a&gt; du porteur comme s’il avait pass&#233; une nuit de sommeil, tout en augmentant son niveau effectif (ou ses DV) de +4 concernant les &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;soins &#224; long terme&lt;/a&gt;. Usage unique.&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maillot-De-Sprinter.html&quot; title=&quot;Maillot de sprinter&quot;&gt;Maillot de sprinter&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour au bout de 24 heures de port, le porteur peut effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; suppl&#233;mentaire par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cartouchi&#232;re-In&#233;puisable.html&quot; title=&quot;Cartouchi&#232;re in&#233;puisable&quot;&gt;Cartouchi&#232;re in&#233;puisable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut contenir 60 &lt;a class=&quot;pagelink&quot; href=&quot;Cartouche-Alchimique-(Arme).html&quot; title=&quot;Cartouche alchimique&quot;&gt;cartouches alchimiques&lt;/a&gt;, 4 armes &#224; feu &#224; une main, 500g de munitions, une corne &#224; poudre et 2 armes &#224; feu &#224; deux mains en rendant ces objets plus faciles d’acc&#232;s.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veste-&#192;-Outils.html&quot; title=&quot;Veste &#224; outils&quot;&gt;Veste &#224; outils&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut convoquer les outils n&#233;cessaires &#224; un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; pendant 24 heures.&lt;/td&gt;&lt;td&gt;1 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veste-Polyvalente.html&quot; title=&quot;Veste polyvalente&quot;&gt;Veste polyvalente&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker jusqu&#39;&#224; 6 objets pesant 500 g au maximum, ainsi que 4 fois un volume 15cm&lt;sup&gt;3&lt;/sup&gt; (2,250 kg maximum) d&#39;&#233;quipement. Contient une &lt;a class=&quot;pagelink&quot; href=&quot;Rations-De-Survie-(Objet).html&quot; title=&quot;Rations de survie&quot;&gt;rations de route&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Outre-(Objet).html&quot; title=&quot;Outre&quot;&gt;outre&lt;/a&gt; remplie d&#39;eau, deux &lt;a class=&quot;pagelink&quot; href=&quot;Bougie-(Objet).html&quot; title=&quot;Bougie&quot;&gt;bougies&lt;/a&gt; et un &lt;a class=&quot;pagelink&quot; href=&quot;Allume-Feu-(Objet).html&quot; title=&quot;Allume-feu&quot;&gt;allume-feu&lt;/a&gt;, recr&#233;&#233;s jusqu&#39;&#224; 1 fois tous les trois jours.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-&#192;-Poches.html&quot; title=&quot;Manteau &#224; poches&quot;&gt;Manteau &#224; poches&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE, UI&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de circonstances de +5 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; pour cacher un objet dedans. Il faut une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour r&#233;cup&#233;rer un objet plac&#233; &#224; l&#39;int&#233;rieur.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gilet-De-M&#233;decin.html&quot; title=&quot;Gilet de m&#233;decin&quot;&gt;Gilet de m&#233;decin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fait office de &lt;a class=&quot;pagelink&quot; href=&quot;Trousse-De-Premiers-Secours-(Objet).html&quot; title=&quot;Trousse de premiers secours&quot;&gt;trousse de premiers secours&lt;/a&gt; infinie. Permet de soigner 1d4 points d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissement temporaire&lt;/a&gt; de caract&#233;ristique avec un test de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-Des-Bas-Fonds.html&quot; title=&quot;Manteau des bas-fonds&quot;&gt;Manteau des bas-fonds&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu&#39;&#224; 5 minutes par jour dans un milieu urbain, peut transformer le porteur en &lt;a class=&quot;pagelink&quot; href=&quot;Cafard-G&#233;ant.html&quot; title=&quot;Cafard, Cafard g&#233;ant&quot;&gt;cafard g&#233;ant&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-De-Vermine-I.html&quot; title=&quot;Forme de vermine I&quot;&gt;forme de vermine I&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;3 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-Des-Bas-Fonds-Sup&#233;rieur.html&quot; title=&quot;Manteau des bas-fonds sup&#233;rieur&quot;&gt;Manteau des bas-fonds sup&#233;rieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu&#39;&#224; 9 minutes par jour dans un milieu urbain, peut transformer le porteur en &lt;a class=&quot;pagelink&quot; href=&quot;Cafard-G&#233;ant.html&quot; title=&quot;Cafard, Cafard g&#233;ant&quot;&gt;cafard venimeux&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-De-Vermine-Ii.html&quot; title=&quot;Forme de vermine II&quot;&gt;forme de vermine II&lt;/a&gt;&lt;/i&gt;) ou en une nu&#233;e de cafards Minuscules (similaires &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-De-Rats.html&quot; title=&quot;Rat, Nu&#233;e de rats&quot;&gt;nu&#233;e de rats&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 37 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;charpe-Du-Champion.html&quot; title=&quot;&#201;charpe du champion&quot;&gt;&#201;charpe du champion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; voit son niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; augment&#233; de 4 pour d&#233;terminer ses aptitudes d’&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMURES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armures&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#COURAGE&quot; title=&quot;Le guerrier&quot;&gt;courage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veste-De-La-Lame-Silencieuse.html&quot; title=&quot;Veste de la Lame silencieuse&quot;&gt;Veste de la lame silencieuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;. Si le porteur est adjacent &#224; un alli&#233; utilisant la &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;, conf&#232;re un bonus de comp&#233;tence de +5 aux tests de Discr&#233;tion.&lt;/td&gt;&lt;td&gt;4 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tunique-Dincantation-Minutieuse.html&quot; title=&quot;Tunique d’Iincantation minutieuse&quot;&gt;Tunique d’incantation minutieuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#CONCENTRATION&quot; title=&quot;Lancer des sorts&quot;&gt;tests de concentration&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veste-Absorbante.html&quot; title=&quot;Veste absorbante&quot;&gt;Veste absorbante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de consommer des potions &#224; dur&#233;e instantan&#233;e ou indiqu&#233;e en &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; round par round.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gilet-D&#233;vasion.html&quot; title=&quot;Gilet d&amp;#39;&#233;vasion&quot;&gt;Gilet d’&#233;vasion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +6 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;. Contient des outils de cambrioleur magiques conf&#233;rant un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gilet-De-Tir-Impitoyable.html&quot; title=&quot;Gilet de tir impitoyable&quot;&gt;Gilet de tir impitoyable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;pistolier&lt;/a&gt; voit le co&#251;t de l’exploit &lt;a class=&quot;pagelink&quot; href=&quot;Exploits.html#BOUTPORTANT&quot; title=&quot;Les exploits du pistolier&quot;&gt;bout portant&lt;/a&gt; r&#233;duit de 1. Permet de tenter une mise &#224; mort contre une cr&#233;ature r&#233;duite &#224; 0 points de vie ou moins par un tir d’arme &#224; feu, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gilet-Du-Traqueur.html&quot; title=&quot;Gilet du traqueur&quot;&gt;Gilet du traqueur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de moral de +1 au premier &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jet d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt;] des armes contre les cr&#233;atures que le porteur a traqu&#233; durant les derni&#232;res 24 heures, le bonus s’&#233;l&#232;ve &#224; +2 si ces cr&#233;atures sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Prisaud&#233;pourvu&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;prise au d&#233;pourvu&lt;/a&gt; et, si le porteur poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemi jur&#233;&lt;/a&gt;, conf&#232;re un bonus de +4 aux jets de confirmation critique contre elles.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Plastron-Proph&#233;tique.html&quot; title=&quot;Plastron proph&#233;tique&quot;&gt;Plastron proph&#233;tique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Augmente les chances de succ&#232;s des sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augure.html&quot; title=&quot;Augure&quot;&gt;augure&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Divination.html&quot; title=&quot;Divination&quot;&gt;divination&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contact-Avec-Les-Plans.html&quot; title=&quot;Contact avec les plans&quot;&gt;contact avec les plans&lt;/a&gt;&lt;/i&gt;. Le porteur peut poser une question de plus ou obtenir une information suppl&#233;mentaire avec les sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion.html&quot; title=&quot;Communion&quot;&gt;communion&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion-Avec-La-Nature.html&quot; title=&quot;Communion avec la nature&quot;&gt;communion avec la nature&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tunique-De-Puissance-D&#233;vastatrice.html&quot; title=&quot;Tunique de puissance d&#233;vastatrice&quot;&gt;Tunique de puissance d&#233;vastatrice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESARMEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;d&#233;sarmement&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESTRUCTION&quot; title=&quot;Les manœuvres offensives&quot;&gt;destruction&lt;/a&gt; d’arme. Un &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html&quot; title=&quot;Le samoura&#239;&quot;&gt;samoura&#239;&lt;/a&gt; peut appliquer la propri&#233;t&#233; d’arme &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Tonnerre.html&quot; title=&quot;tonnerre (propri&#233;t&#233;)&quot;&gt;tonnerre&lt;/a&gt; &#224; un coup critique r&#233;ussit sur la cible de son &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html#DEFI&quot; title=&quot;Le samoura&#239;&quot;&gt;d&#233;fi&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vareuse-De-Sorci&#232;re-Ricaneuse.html&quot; title=&quot;Vareuse de sorci&#232;re ricaneuse&quot;&gt;Vareuse de sorci&#232;re ricaneuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Une &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;re&lt;/a&gt; obtient le &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Ricanement&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;ricanement&lt;/a&gt; et, si elle le poss&#232;de d&#233;j&#224;, elle peut l’utiliser 2 fois par jour par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Uniforme-Resplendissant.html&quot; title=&quot;Uniforme resplendissant&quot;&gt;Uniforme resplendissant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#TACTICIEN&quot; title=&quot;Le chevalier&quot;&gt;tacticien&lt;/a&gt; en obtient une utilisation suppl&#233;mentaire par jour qui affecte tous les alli&#233;s &#224; 18 m ou moins.&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blouse-Du-B&#226;tard-Impudent.html&quot; title=&quot;Blouse du b&#226;tard impudent&quot;&gt;Blouse du b&#226;tard impudent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur#Panache.html&quot; title=&quot;panache&quot;&gt;panache&lt;/a&gt; en r&#233;cup&#232;re 1 point &#224; chaque fois qu’il re&#231;oit des d&#233;g&#226;ts d’un coup critique confirm&#233;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chemise-De-Linsoup&#231;onnable.html&quot; title=&quot;Chemise de l&amp;#39;insoup&#231;onnable&quot;&gt;Chemise de l&#39;insoup&#231;onnable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les autres cr&#233;atures ignorent facilement le porteur s&#39;il n&#39;est pas explicitement hostile.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chemise-Enflamm&#233;e.html&quot; title=&quot;Chemise enflamm&#233;e&quot;&gt;Chemise enflamm&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;En situation de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#LUTTE&quot; title=&quot;Les manœuvres offensives&quot;&gt;lutte&lt;/a&gt;, inflige 1d6+10 points de d&#233;g&#226;ts de feu &#224; l’adversaire du porteur chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, l’adversaire prend feu pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; apr&#232;s la fin de la lutte.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tunique-En-Peau-De-Serpent.html&quot; title=&quot;Tunique en peau de serpent&quot;&gt;Tunique en peau de serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’armure de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; et un bonus de r&#233;sistance de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre le poison.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baudrier-Du-Tueur.html&quot; title=&quot;Baudrier du tueur&quot;&gt;Baudrier du tueur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt; voit son niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt; augment&#233; de 5 pour d&#233;terminer les effets de ses capacit&#233;s de &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#TUEUR&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;tueur&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#TUEURSUPERIEUR&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;tueur sup&#233;rieur&lt;/a&gt;. Un non-inquisiteur obtient ces capacit&#233;s comme un inquisiteur de niveau 5, uniquement avec une armes accroch&#233;e &#224; ce baudrier pendant 24 heures.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chemise-De-Libert&#233;.html&quot; title=&quot;Chemise de libert&#233;&quot;&gt;Chemise de libert&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Libert&#233;-De-Mouvement.html&quot; title=&quot;Libert&#233; de mouvement&quot;&gt;libert&#233; de mouvement&lt;/a&gt;&lt;/i&gt; pendant 10 minutes.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-Du-Fid&#232;le-R&#233;ceptacle.html&quot; title=&quot;Manteau du fid&#232;le r&#233;ceptacle&quot;&gt;Manteau du fid&#232;le r&#233;ceptacle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les cr&#233;atures soign&#233;es par les &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisations d&#39;&#233;nergie&lt;/a&gt; du porteur b&#233;n&#233;ficient des effets d&#39;une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt; pendant 1 minute, et toutes les cr&#233;atures bless&#233;es par celles-ci sont soumises aux effets d&#39;une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Impr&#233;cation.html&quot; title=&quot;Impr&#233;cation&quot;&gt;impr&#233;cation&lt;/a&gt;&lt;/i&gt; pendant la m&#234;me dur&#233;e et subissent des d&#233;g&#226;ts suppl&#233;mentaires.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veston-De-Lempoisonneur.html&quot; title=&quot;Veston de l’empoisonneur&quot;&gt;Veston de l’empoisonneur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut cr&#233;er une fiole d’un &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poison&lt;/a&gt; valant jusqu’&#224; 300 po inutilisable au bout d’une heure.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Veston-De-Lempoisonneur-Sup&#233;rieur.html&quot; title=&quot;Veston de l’empoisonneur sup&#233;rieur&quot;&gt;Veston de l’empoisonneur sup&#233;rieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Veston de l’Empoisonneur&lt;/i&gt; mais peut &#233;galement, une fois par jour, cr&#233;er une fiole d’un &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poison&lt;/a&gt; valant jusqu’&#224; 4 000 po inutilisable au bout d’une heure.&lt;/td&gt;&lt;td&gt;| 58 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baudrier-De-Stabilit&#233;-Magique.html&quot; title=&quot;Baudrier de stabilit&#233; magique&quot;&gt;Baudrier de stabilit&#233; magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker jusqu&#39;&#224; deux carquois de &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreaux d&#39;arbal&#232;te&lt;/a&gt;, un carquois de &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt;, ou 40 &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balles&lt;/a&gt; ou cartouches d&#39;arme &#224; feu, ainsi qu&#39;une arme. Conf&#232;re un bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; contre les effets de la &lt;a class=&quot;pagelink&quot; href=&quot;Magie-Primordiale.html&quot; title=&quot;La magie primordiale&quot;&gt;magie primordiale&lt;/a&gt;, m&#234;me si le porteur n&#39;est pas un lanceur de sorts.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cartouchi&#232;re-Du-Gardien-De-La-Mort.html&quot; title=&quot;Cartouchi&#232;re du gardien de la mort&quot;&gt;Cartouchi&#232;re du gardien de la mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut manifester quatre pouvoirs visants &#224; combattre les morts-vivants. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le porteur peut utiliser un de ces pouvoirs sans en d&#233;penser d&#39;utilisation journali&#232;re.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Veste-Du-Cafard.html&quot; title=&quot;Veste du cafard&quot;&gt;Veste du cafard&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; obtient le &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#TALENT&quot; title=&quot;Le roublard&quot;&gt;talent&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#r&#233;silience&quot; title=&quot;Les talents de roublard&quot;&gt;r&#233;silience&lt;/a&gt; et, s’il le poss&#232;de d&#233;j&#224;, il lui conf&#232;re 2 points de vie par niveau de roublard.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gilet-De-Stabilit&#233;-Mutag&#232;ne.html&quot; title=&quot;Gilet de stabilit&#233; mutag&#232;ne&quot;&gt;Gilet de stabilit&#233; mutag&#232;ne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; ne subit plus les malus aux caract&#233;ristiques mentales inflig&#233;es par ses &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#MUTAGENE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;mutag&#232;nes&lt;/a&gt;. Permet de stocker le n&#233;cessaire &#224; la confection de produits alchimiques.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chemise-Du-Mangeur-De-Malchance.html&quot; title=&quot;Chemise du mangeur de malchance&quot;&gt;Chemise du mangeur de malchance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsqu&#39;un alli&#233; est soumis &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;mal&#233;diction&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt;, un mauvais sort ou un autre effet qui le forcerait &#224; lancer plusieurs fois le m&#234;me jet pour conserver le pire r&#233;sultat, un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;tengu&lt;/a&gt; peut tenter de dissiper l&#39;effet pour obtenir des &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort#Pvtemporaires.html&quot; title=&quot;points de vie temporaires&quot;&gt;points de vie temporaires&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;22 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Linceul-Spectral.html&quot; title=&quot;Linceul spectral&quot;&gt;Linceul spectral&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de voir les cr&#233;atures invisibles et &#233;th&#233;r&#233;es (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt;). Une fois par jour, permet au porteur de devenir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Intangible&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;intangible&lt;/a&gt; et de gagner une vitesse de vol &#233;gale &#224; sa vitesse de base pednant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;26 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#232;lerine-Dimmortalit&#233;.html&quot; title=&quot;P&#232;lerine d’immortalit&#233;&quot;&gt;P&#232;lerine d’immortalit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Civil-Et-Mensurations.html#AGE&quot; title=&quot;&#201;tat civil et mensurations&quot;&gt;&#226;ge m&#251;r&lt;/a&gt; ne subit plus les malus aux caract&#233;ristiques physiques impos&#233;s par son &#226;ge.&lt;/td&gt;&lt;td&gt;50 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baudrier-Mis&#233;ricordieux.html&quot; title=&quot;Baudrier mis&#233;ricordieux&quot;&gt;Baudrier mis&#233;ricordieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; peut choisir 3 &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ces&lt;/a&gt; suppl&#233;mentaires qui font effet pendant 24 heures chaque jour. Lorsque qu’il utilise une &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce&lt;/a&gt; pour r&#233;primer un effet de mal&#233;diction, de maladie ou de poison pendant 1 heure, il la supprime &#224; la place.&lt;/td&gt;&lt;td&gt;60 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasuble-De-La-Foi.html&quot; title=&quot;Chasuble de la foi&quot;&gt;Chasuble de la foi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/Mal.&lt;/td&gt;&lt;td&gt;76 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasuble-De-R&#233;sistance-&#192;-La-Magie.html&quot; title=&quot;Chasuble de r&#233;sistance &#224; la magie&quot;&gt;Chasuble de r&#233;sistance &#224; la magie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; de 21.&lt;/td&gt;&lt;td&gt;90 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
